<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue'
import {weights,readSavedScores,getTotal,getGrade,formatScore,displayScore,studentSummaryKey} from './grading'
import {defaultSummary,paras,details,annotations,strengths,improvements} from './reportData'
import {levelFor} from './schoolRules'
const props=defineProps(['rules'])
const scores=ref(readSavedScores()),summary=ref(defaultSummary)
function refresh(){scores.value=readSavedScores();try{const saved=JSON.parse(localStorage.getItem(studentSummaryKey(1)));summary.value=typeof saved==='string'?saved:defaultSummary}catch{summary.value=defaultSummary}}
function sync(event){if(event.key===null||event.key==='essay-grade-scores-example52'||event.key===studentSummaryKey(1))refresh()}
refresh();onMounted(()=>window.addEventListener('storage',sync));onUnmounted(()=>window.removeEventListener('storage',sync))
const names=['內容','表達','結構','標點字體']
const colors=['#245cff','#16b98d','#ee9d16','#8c5cec']
const view=ref('image'),panel=ref('score'),activeNote=ref(null)
const total=computed(()=>formatScore(getTotal(scores.value)))
const grade=computed(()=>getGrade(getTotal(scores.value)))
const paragraphNodes=ref([])
function segments(text,index){const note=annotations.find(n=>n.paragraph===index);if(!note)return [{text}];const start=text.indexOf(note.quote);if(start<0)return [{text}];return [{text:text.slice(0,start)},{text:note.quote,note},{text:text.slice(start+note.quote.length)}]}
function openNote(note){activeNote.value=note.id;panel.value='notes'}
async function locate(note){activeNote.value=note.id;view.value='text';await nextTick();paragraphNodes.value[note.paragraph]?.scrollIntoView({behavior:'smooth',block:'center'})}
</script>
<template>
<section class="student-report" role="tabpanel" id="student-panel" aria-labelledby="student-tab">
  <header class="student-heading"><strong>✧ AI 批改報告</strong></header>
  <div class="student-layout">
    <section class="student-paper">
      <div class="student-paper-tools"><b>▤ 作文內容</b><div class="student-segments" aria-label="作文檢視方式"><button :class="{selected:view==='image'}" @click="view='image'">圖片批改</button><button :class="{selected:view==='text'}" @click="view='text'">文字批改</button></div><button class="student-typo" role="switch" :aria-checked="false" disabled title="暫無可定位的錯字記錄"><i></i>錯字</button></div>
      <div class="student-paper-body"><h2>懂得卻懂</h2><div v-if="view==='image'" class="student-image"><img :src="'./original-page.png'" alt="作文原文圖片節選"><p>作文圖片節選</p></div><article v-else class="student-essay"><p v-for="(p,i) in paras" :key="i" :ref="el=>paragraphNodes[i]=el"><template v-for="(part,j) in segments(p,i)" :key="j"><button v-if="part.note" :class="['annotation-anchor',{good:part.note.kind==='佳句賞析',selected:activeNote===part.note.id}]" :aria-label="part.note.kind+'：'+part.text" @click="openNote(part.note)">{{part.text}}</button><span v-else>{{part.text}}</span></template></p></article></div>
    </section>
    <aside class="student-analysis">
      <div class="student-analysis-tabs" role="tablist" aria-label="報告內容"><button role="tab" :aria-selected="panel==='score'" @click="panel='score'">▥ 評分分析</button><button role="tab" :aria-selected="panel==='notes'" @click="panel='notes'">✎ 批註詳情</button></div>
      <template v-if="panel==='score'">
        <section class="student-score-card"><div class="score-badge-row"><span class="requirement-badge">需求</span></div><div class="student-results"><div v-for="item in ['percent','grade','level'].filter(key=>rules.display.includes(key))" :key="item" class="student-total"><span v-if="item!=='grade'">{{item==='level'?'等級':'總分'}}</span><strong>{{item==='level'?levelFor(props.rules,total):item==='grade'?grade:displayScore(total)}}<small v-if="item==='percent'">/100</small></strong></div></div>
        <div v-for="(name,i) in names" :key="name" class="student-dimension"><div><b>{{name}}</b><span>{{displayScore(scores[i] * weights[i])}}<small> / {{weights[i] * 10}}</small></span></div><div class="student-meter"><i :style="{width:scores[i]*10+'%',background:colors[i]}"></i></div><p class="dimension-comment">{{details[i]}}</p></div></section>
        <section class="student-comment"><h3>作文總評</h3><p>{{summary}}</p></section><section class="student-comment"><h3>整體優點</h3><ul><li v-for="text in strengths" :key="text">{{text}}</li></ul></section><section class="student-comment"><h3>整體改善建議</h3><ul><li v-for="text in improvements" :key="text">{{text}}</li></ul></section>
      </template>
      <section v-else class="student-comment student-notes"><h3>批註詳情</h3><article v-for="note in annotations" :key="note.id" :class="{selected:activeNote===note.id}"><b>{{note.kind}}</b><blockquote>{{note.quote}}</blockquote><p>{{note.text}}</p><button class="locate-note" @click="locate(note)">查看原文</button></article></section>
    </aside>
  </div>
</section>
</template>
<style scoped>
.student-report{margin-top:64px;min-height:calc(100vh - 64px);background:#f7f9fc;color:#293549;font-size:14px}.student-heading{height:58px;background:white;display:flex;align-items:center;justify-content:space-between;padding:0 28px;border-bottom:1px solid #edf0f5}.student-heading strong{font-size:19px}.student-heading>span{font-size:12px;color:#8d98aa}.student-layout{max-width:1440px;margin:auto;padding:24px;display:grid;grid-template-columns:minmax(0,1.75fr) minmax(330px,1fr);gap:16px;align-items:start}.student-paper{background:#fffef9;border:1px solid #e8edf3;border-radius:24px;overflow:hidden}.student-paper-tools{display:flex;align-items:center;gap:14px;padding:18px;background:#f9fbfd;border-bottom:1px solid #edf0f5;flex-wrap:wrap}.student-paper-tools>b{margin-right:auto;font-size:13px}.student-segments{display:flex;padding:4px;background:#f2f6fb;border:1px solid #e9eef6;border-radius:13px;gap:4px}.student-segments button{border:0;border-radius:9px;padding:10px 14px;background:transparent;color:#8794a9;font-size:13px;font-weight:600}.student-segments .selected{background:white;color:#245cff;box-shadow:0 2px 6px #23447709}.student-typo{display:flex;align-items:center;gap:8px;border:0;background:#fff0f4;color:#eb5276;border-radius:20px;padding:7px 10px;font-size:12px}.student-typo i{width:28px;height:16px;background:#b9c2cf;border-radius:20px;position:relative}.student-typo i:after{content:'';position:absolute;width:12px;height:12px;border-radius:50%;background:white;left:2px;top:2px}.student-typo i.on{background:#ff7896}.student-typo i.on:after{left:14px}.student-legend{font-size:10px;color:#8b97a8}.student-paper-body{padding:30px}.student-paper-body h2{text-align:center;font-size:21px;letter-spacing:2px;line-height:1.7}.student-demo{font-size:11px;color:#919cac;text-align:center;margin:10px 0 24px}.student-image{padding:18px;border:1px solid #edf0f5;border-radius:22px;background:white}.student-image img{display:block;width:100%;height:auto}.student-image p{font-size:11px;text-align:center;color:#8d98aa;margin:12px 0 0}.student-essay{background:white;border-radius:22px;padding:25px;border:1px solid #edf0f5;font-family:serif;font-size:18px;line-height:2}.student-essay p{margin:0 0 24px;text-indent:2em}.student-good{background:#e4f5ea;color:inherit}.student-warning{text-decoration:underline wavy #e8a246;text-underline-offset:5px}.student-analysis{position:static!important;inset:auto!important;background:transparent!important;width:auto!important;border:0!important}.student-analysis-tabs{display:flex;border:1px solid #e8edf3;border-radius:14px;padding:5px;background:#f3f7fd;gap:5px;margin-bottom:16px}.student-analysis-tabs button{flex:1;border:0;background:transparent;padding:12px;color:#8d98aa;font-weight:600;border-radius:10px}.student-analysis-tabs button[aria-selected=true]{background:white;color:#245cff}.student-score-card,.student-comment{padding:22px;border:1px solid #e8edf3;border-radius:24px;background:white}.student-scale{margin-bottom:20px}.student-scale button{flex:1}.student-score-label{background:#245cff;border-radius:20px;padding:7px 13px;color:white;font-size:11px;font-weight:600}.student-total{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:20px 0}.student-total strong{font-size:48px;color:#245cff;line-height:1.1}.student-total small{font-size:16px;margin-left:5px;color:#bdc6d4;font-weight:500}.student-dimension{border-radius:15px;background:#f8fafc;padding:15px;margin-bottom:12px}.student-dimension>div:first-child{display:flex;justify-content:space-between;gap:8px;font-size:13px}.student-dimension small{color:#b4bdca}.student-dimension em{font-style:normal;display:block;text-align:right;font-size:11px;margin-top:4px;color:#77859a}.student-meter{height:9px;background:#e8edf2;border-radius:10px;overflow:hidden;margin-top:10px}.student-meter i{display:block;height:100%;border-radius:10px}.student-score-note{font-size:11px;color:#93a0b3;line-height:1.6;margin:18px 0 0}.student-comment{margin-top:16px}.student-comment h3{font-size:17px;margin:0 0 6px}.student-comment>span{font-size:11px;letter-spacing:2px;color:#7493d5}.student-comment p{font-size:14px;line-height:1.9;margin:16px 0 0}.student-notes article{padding:18px 0;border-bottom:1px solid #eef1f5}.student-notes small{display:block;margin-top:18px;color:#93a0b3}@media(max-width:850px){.student-layout{padding:14px;gap:12px;grid-template-columns:minmax(0,1fr) 300px}.student-paper-body{padding:18px}.student-score-card,.student-comment{padding:16px}.student-paper-tools{gap:8px}.student-legend{display:none}.student-total strong{font-size:38px}}@media(max-width:650px){.student-layout{grid-template-columns:1fr}.student-heading{padding:0 16px}.student-heading>span{font-size:10px}.student-essay{padding:18px}.student-report{overflow-x:hidden}}

.student-typo:disabled{cursor:not-allowed;opacity:.55}.annotation-anchor{display:inline;border:0;border-radius:3px;padding:0;background:#fff2d6;color:inherit;font:inherit;text-align:inherit;cursor:pointer;text-indent:0}.annotation-anchor.good{background:#e4f5ea}.annotation-anchor.selected{outline:2px solid #245cff}.annotation-anchor:focus-visible,.locate-note:focus-visible{outline:2px solid #245cff;outline-offset:2px}.student-essay p{scroll-margin-top:100px}.student-notes article.selected{border-left:3px solid #245cff;padding-left:12px}.student-notes blockquote{margin:12px 0;padding:10px;background:#f5f8fc;color:#52627a;line-height:1.8}.locate-note{min-height:44px;margin-top:12px;padding:8px 14px;border:1px solid #dce5f2;border-radius:8px;background:white;color:#245cff}.student-comment ul{padding-left:22px;line-height:1.9}.student-comment li+li{margin-top:8px}.dimension-comment{font-size:14px;line-height:1.8;color:#52627a;margin:10px 0 0}.student-total{flex-wrap:wrap}
.student-grade{display:inline-flex;align-items:center;gap:9px;padding:12px 16px;border:1px solid #e9eef8;border-radius:999px;background:#f5f8ff;color:#245cff;font-size:14px;font-weight:600;line-height:22px;white-space:nowrap}.student-grade svg{width:22px;height:22px;flex-shrink:0;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
</style>

<style scoped>.student-results{display:flex;align-items:baseline;gap:12px;overflow-x:auto;padding:8px 0 16px}.student-results .student-total{flex:none;flex-wrap:nowrap;align-items:baseline;white-space:nowrap;margin:0;gap:4px}.student-results strong{font-size:18px}.student-results small{font-size:12px;margin-left:1px}</style>

<style scoped>.score-badge-row{display:flex;justify-content:flex-end;margin-bottom:6px}</style>
